    import json, re, time
from pathlib import Path

# 触发集：只有三个建计划工具才可能产生"新计划待委托"（worker 自身调 update_plan 等天然短路）
TRIGGERS = {"create_plan", "commit_spec", "join_plan"}
# plan_id 提取正则：覆盖三种文案（与 session.py 施工源头回搜同源）
#   create_plan  → "已创建计划 p_xxxxxxxx（N 步）："
#   commit_spec  → "✅ 用户已批准 spec s_xxx！已生成 plan p_xxxxxxxx（N 步）并设为活动计划"
#   join_plan    → "已加入计划 p_xxxxxxxx（当前 N 步）："
_RX_PID = re.compile(r"(?:已创建计划|已生成\s+plan|已加入计划)\s+(p_[0-9a-fA-F]+)")


def _mark_path() -> Path:
    """幂等标记文件（repo 级，跨 session 共享）：join_plan 进来的其它 session 不会对已委托计划重复派发；
    重启不丢（替代旧 session.extra_state['_plan_dispatch']——残留无消费者，无害不迁移）。"""
    return Path(".agent/construction_dispatch.json")


def _plan_path(pid: str) -> Path:
    """计划文件真源：~/.agt/repos/<hash>/plans/<pid>.json（与 plan_tools 同源，走 repo_plans_dir）。"""
    from session import repo_plans_dir
    return repo_plans_dir(Path.cwd()) / f"{pid}.json"


def _build_dispatch_prompt(plan: dict) -> str:
    """装配施工牌（移植原引擎 _construction_dispatch_prompt，格式逐字一致——worker 首轮即得全图）：
    设计 + 步骤原文完整进 prompt；prompt 是派发时刻快照（含初始状态），续派/补派由主 Agent 手写指令。"""
    pid = str(plan.get("id", "") or "")
    title = str(plan.get("title", "") or "")
    steps = plan.get("steps") or []
    design = str(plan.get("design", "") or "").strip()
    parts = [f"开始施工：【施工牌】{pid}（{title} · {len(steps)} 步）——设计与步骤原文如下："]
    if design:
        parts.append(f"\n## 设计\n{design}")
    if steps:
        parts.append(f"\n## 步骤（共 {len(steps)} 步，逐项推进）")
        for i, s in enumerate(steps):
            parts.append(f"{i + 1}. {s.get('description', '')}")
    parts.append("\n按你的角色约定推进，用 update_plan 标进度（状态轻量视图每轮装配注入）。"
                 "完成后按汇报格式给结论（完成到第几步 / 改动清单 / 验证结果 / 遗留风险）。")
    return "\n".join(parts)


async def main(args):
    """闸门：①tool_name ∈ 触发集否则短路；②正则提取 plan_id（结果文本无 id=失败/拒绝→短路）；
    ③读计划文件——无步骤/全 completed → 清幂等标记短路（新计划重新委托，同旧引擎语义）；
    ④同 plan_id 已委托（文件级标记）→ 幂等短路；⑤装配施工牌全文输出。
    任何短路只影响本钩子（inject=False 不注入），绝不影响主流程。"""
    tn = str(args.params.get("tool_name") or "")
    tr = str(args.params.get("tool_result") or "")
    _short = {"should_dispatch": False, "prompt_text": "", "plan_id": "",
              "agent_id": "", "n_steps": 0, "note": ""}
    if tn not in TRIGGERS:
        return {**_short, "reason": f"工具 {tn} 非建计划工具（短路）"}
    m = _RX_PID.search(tr)
    if not m:
        return {**_short, "reason": f"{tn} 结果未含 plan_id（建计划失败/被拒绝，短路）"}
    pid = m.group(1)
    aid = f"worker-{pid}"
    mp = _mark_path()
    try:
        mark = json.loads(mp.read_text(encoding="utf-8")) if mp.exists() else {}
    except Exception:
        mark = {}
    # 计划本体：读不到=保守不派发（新进程首拍目录未建等瞬时态，下次触发自然重试）
    try:
        plan = json.loads(_plan_path(pid).read_text(encoding="utf-8"))
    except Exception as e:
        return {**_short, "reason": f"读计划 {pid}.json 失败: {type(e).__name__}: {e}（短路）"}
    steps = plan.get("steps") or []
    done_all = bool(steps) and all(str(s.get("status")) == "completed" for s in steps)
    if not pid or not steps or done_all:
        # 计划完成/无计划：委托标记失效（下次新计划重新委托）——同旧引擎 _d.clear() 语义
        if mark:
            try:
                mp.unlink(missing_ok=True)
            except Exception:
                pass
        return {**_short, "reason": f"{pid} 无步骤或已全完成（标记已清，短路）"}
    if str(mark.get("plan_id") or "") == pid and str(mark.get("agent_id") or ""):
        return {**_short, "reason": f"{pid} 已委托给 {mark.get('agent_id')}（幂等短路）"}
    note = (f"施工已委托 {aid}（计划 {pid} · {len(steps)} 步）：这条计划由 worker 执行，"
            f"你不必再自己动手。worker 完成会自动汇报进你的 inbox——"
            f"收到后用 update_plan 记账并向用户汇总；期间可正常响应用户。")
    return {"should_dispatch": True, "prompt_text": _build_dispatch_prompt(plan),
            "plan_id": pid, "agent_id": aid, "n_steps": len(steps),
            "note": note, "reason": f"待派发 {aid}"}













