    import json, time
from pathlib import Path
async def main(args):
    """派发成功：写 repo 级幂等标记文件（.agent/construction_dispatch.json）——
    跨 session 防重复派发；重启不丢（替代旧 extra_state['_plan_dispatch']）。
    写失败不阻断（最坏情况=重启后对同计划重派一次，worker 复用实例接续，幂等兜底可接受）。"""
    pid = str(args.params.get("plan_id") or "")
    aid = str(args.params.get("agent_id") or "")
    note = str(args.params.get("note") or "")
    try:
        d = Path(".agent"); d.mkdir(parents=True, exist_ok=True)
        (d / "construction_dispatch.json").write_text(
            json.dumps({"plan_id": pid, "agent_id": aid, "ts": time.time()},
                       ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass
    return {"injected": True, "result": note, "message": note}
